// MotionBenchMaker Panda problems (gen/problems_panda.c, generated by tools/gen_problems.py).
#pragma once
#include <stdint.h>

enum { PRIM_BOX = 0, PRIM_CYLINDER = 1 };

typedef struct {
    uint8_t type;
    float pos[3];
    float rot[9];   // row-major rotation matrix
    float dim[3];   // box: half extents; cylinder: radius, length, 0
} prim_t;

typedef struct {
    uint8_t scene;
    uint8_t valid;  // VAMP's flag: start and goal collision-free against the primitives
    uint16_t index;
    uint16_t prim_off, n_prims;
    float start[7], goal[7];
} problem_t;

extern const int n_scenes;
extern const char *const scene_names[];
extern const int n_problems;
extern const problem_t problems[];
extern const prim_t prims[];
